let spkCurrentQuestionIndex = 0;
let spkScore = 0;
let spkSelectedOptionIndex = null;
let spkUserAnswers = [];
let spkIsFeedbackMode = false;

const spkQuestionEl = document.getElementById("spk-question");
const spkOptionsEl = document.getElementById("spk-options");
const spkNextBtn = document.getElementById("spk-next-btn");
const spkProgressEl = document.getElementById("spk-progress");
const spkQuizScreen = document.getElementById("spk-quiz-screen");
const spkResultScreen = document.getElementById("spk-result-screen");
const spkFinalScoreEl = document.getElementById("spk-final-score");

function spkLoadQuestion() {
 spkSelectedOptionIndex = null;
 spkIsFeedbackMode = false;
 spkNextBtn.style.display = "none";
 spkNextBtn.innerHTML = 'Sonraki Soru &raquo;';

 // Feedback alanını temizle
 const feedbackContainer = document.getElementById("spk-feedback-container");
 feedbackContainer.style.display = "none";
 feedbackContainer.innerHTML = "";

 const currentQuizData = spkQuizData[spkCurrentQuestionIndex];
 spkQuestionEl.innerText = currentQuizData.question;
 spkProgressEl.innerText = (spkCurrentQuestionIndex + 1) + " / " + spkQuizData.length;

 spkOptionsEl.innerHTML = "";

 currentQuizData.options.forEach((optionText, index) => {
 const btn = document.createElement("button");
 btn.innerText = optionText;
 btn.classList.add("spk-option-btn");
 btn.onclick = () => spkSelectOption(index, btn);
 spkOptionsEl.appendChild(btn);
 });
}

function spkSelectOption(index, selectedBtn) {
 spkSelectedOptionIndex = index;

 const allBtns = spkOptionsEl.querySelectorAll(".spk-option-btn");
 allBtns.forEach(btn => btn.classList.remove("selected"));

 selectedBtn.classList.add("selected");
 spkNextBtn.style.display = "inline-block";
}

function spkNextQuestion() {
 const currentData = spkQuizData[spkCurrentQuestionIndex];

 if (spkSelectedOptionIndex === null) return;

 if (!spkIsFeedbackMode) {
 // === 1. TIKLAMA: CEVABI ONAYLA VE SONUCU GÖSTER ===
 spkUserAnswers[spkCurrentQuestionIndex] = spkSelectedOptionIndex;

 const isCorrect = spkSelectedOptionIndex === currentData.answerIndex;
 if (isCorrect) spkScore++;

 spkShowFeedback(isCorrect, spkSelectedOptionIndex, currentData.answerIndex, currentData.options[currentData.answerIndex]);

 spkIsFeedbackMode = true;
 spkNextBtn.innerHTML = 'Sonraki Soru &raquo;';
 } else {
 // === 2. TIKLAMA: SONRAKİ SORUYA GEÇ ===
 spkIsFeedbackMode = false;
 spkSelectedOptionIndex = null;
 spkCurrentQuestionIndex++;

 if (spkCurrentQuestionIndex < spkQuizData.length) {
 spkLoadQuestion();
 } else {
 spkShowResults();
 }
 }
}

function spkShowFeedback(isCorrect, userIndex, correctIndex, correctText) {
 const allBtns = spkOptionsEl.querySelectorAll(".spk-option-btn");

 allBtns.forEach((btn, idx) => {
 btn.disabled = true;
 btn.classList.remove("selected");

 if (idx === correctIndex) {
 btn.classList.add("correct");
 }
 if (idx === userIndex && idx !== correctIndex) {
 btn.classList.add("wrong");
 }
 });

 const feedbackContainer = document.getElementById("spk-feedback-container");
 feedbackContainer.style.display = "block";

 let messageHTML = '';
 if (isCorrect) {
 messageHTML = `
 <div class="spk-feedback correct">
 <span style="font-size:24px;">✅</span>
 <div>Tebrikler! Doğru cevap verdiniz.</div>
 </div>
 `;
 } else {
 messageHTML = `
 <div class="spk-feedback wrong">
 <span style="font-size:24px;">❌</span>
 <div>Yanlış cevap.<br>Doğru cevap: <strong>${correctText}</strong></div>
 </div>
 `;
 }
 feedbackContainer.innerHTML = messageHTML;
}

function spkShowResults() {
 spkQuizScreen.style.display = "none";
 spkResultScreen.style.display = "block";
 spkFinalScoreEl.innerText = spkScore;

 const reviewList = document.getElementById("spk-review-list");
 reviewList.innerHTML = "";

 spkQuizData.forEach((q, index) => {
 const userAns = spkUserAnswers[index];
 const correctAnsIndex = q.answerIndex;
 const isCorrect = userAns === correctAnsIndex;

 const userOptionText = (userAns !== null && userAns !== undefined) 
 ? q.options[userAns] 
 : 'Cevap verilmedi';

 const correctOptionText = q.options[correctAnsIndex];

 const itemHTML = `
 <div style="margin-bottom: 25px; padding: 20px; background: #f8fafc; border-radius: 8px; border-left: 5px solid ${isCorrect ? '#22c55e' : '#ef4444'};">
 <div style="display: flex; justify-content: space-between; margin-bottom: 12px;">
 <span style="font-weight: 600; color: #1d2327;">Soru ${index + 1}</span>
 <span style="padding: 4px 14px; border-radius: 9999px; font-size: 13px; font-weight: 600; background: ${isCorrect ? '#ecfdf5' : '#fef2f2'}; color: ${isCorrect ? '#10b981' : '#ef4444'};">
 ${isCorrect ? 'DOĞRU' : 'YANLIŞ'}
 </span>
 </div>
 <p style="font-weight: 500; margin-bottom: 18px; line-height: 1.5;">${q.question}</p>

 <div style="display: flex; flex-direction: column; gap: 10px;">
 <div style="display: flex; align-items: center; gap: 12px;">
 <span style="font-weight:600; color: #64748b; min-width: 60px;">Sizin Cevabınız:</span>
 <span style="flex:1; padding: 12px 16px; background: #fff; border-radius: 6px; border: 2px solid ${userAns === correctAnsIndex ? '#22c55e' : '#ef4444'};">
 ${userOptionText}
 </span>
 </div>
 <div style="display: flex; align-items: center; gap: 12px;">
 <span style="font-weight:600; color: #10b981; min-width: 60px;">Doğru Cevap:</span>
 <span style="flex:1; padding: 12px 16px; background: #fff; border-radius: 6px; border: 2px solid #22c55e;">
 ${correctOptionText}
 </span>
 </div>
 </div>
 </div>`;
 reviewList.innerHTML += itemHTML;
 });
}

// İlk soruyu yükle
spkLoadQuestion();
</script>
